1	import { rubbingTypeOrder, type RubbingType } from "@pirate-sea-race/content/objectives";
2	import { hashState } from "../hash.js";
3	import { nextInt } from "../random.js";
4	import {
5	  requireId,
6	  requireInteger,
7	  sectorName,
8	  sectorOf,
9	  type CarrierSnapshot,
10	  type CarrierSnapshotEntry,
11	  type IntelConfig,
12	  type IntelLeadReason,
13	  type IntelLeadTarget,
14	  type IntelMessage,
15	  type IntelMessageBody,
16	  type IntelPlayerState,
17	  type IntelPlayerView,
18	  type IntelState,
19	  type IntelStepResult,
20	  type IntelWorldView,
21	  type JournalRumor,
22	  type PendingSighting,
23	  type PendingSightingType,
24	  type SectorRef,
25	  type TargetedRumorOutcome,
26	  type TargetedRumorRequest,
27	  type TargetedRumorResult,
28	} from "./state.js";
29	
30	/** Lowest id by UTF-16 code units, independent of locale. */
31	function compareIds(a: string, b: string): number {
32	  return a < b ? -1 : a > b ? 1 : 0;
33	}
34	
35	function byTypeOrder(a: RubbingType, b: RubbingType): number {
36	  return rubbingTypeOrder(a) - rubbingTypeOrder(b);
37	}
38	
39	// ---------------------------------------------------------------------------------------------------------------------
40	// Reading the world view.
41	
42	interface WorldIndex {
43	  readonly tick: number;
44	  readonly players: ReadonlyMap<string, IntelPlayerView>;
45	  /** Each player's held types (carried or reserved in a duel), in type order. */
46	  readonly held: ReadonlyMap<string, readonly RubbingType[]>;
47	  readonly sources: readonly { readonly type: RubbingType; readonly island: number; readonly sector: number }[];
48	  readonly caches: readonly { readonly type: RubbingType; readonly sector: number }[];
49	  readonly carriers: readonly CarrierSnapshotEntry[];
50	}
51	
52	/** Refuses a malformed view: a tick not after `after`, duplicate ids, unknown types, islands or carriers, a doubled type. */
53	function readView(config: IntelConfig, view: IntelWorldView, after: number): WorldIndex {
54	  requireInteger(view.tick, "tick");
55	  if (view.tick <= after) throw new RangeError(`expected a tick after ${after}, got ${view.tick}`);
56	  const players = new Map<string, IntelPlayerView>();
57	  for (const player of view.players) {
58	    requireId(player.id, "player id");
59	    if (players.has(player.id)) throw new RangeError(`player ${player.id} appears twice`);
60	    requireInteger(player.x, `${player.id}.x`);
61	    requireInteger(player.y, `${player.id}.y`);
62	    players.set(player.id, player);
63	  }
64	  const ids = new Set<string>();
65	  const held = new Map<string, RubbingType[]>([...players.keys()].map((id) => [id, []]));
66	  const sources: { type: RubbingType; island: number; sector: number }[] = [];
67	  const caches: { type: RubbingType; sector: number }[] = [];
68	  const carriers: CarrierSnapshotEntry[] = [];
69	  for (const rubbing of view.rubbings) {
70	    requireId(rubbing.id, "rubbing id");
71	    if (ids.has(rubbing.id)) throw new RangeError(`rubbing ${rubbing.id} appears twice`);
72	    ids.add(rubbing.id);
73	    if (!config.types.includes(rubbing.type)) throw new RangeError(`rubbing ${rubbing.id} has a type outside the preset: ${String(rubbing.type)}`);
74	    const place = rubbing.place;
75	    switch (place.kind) {
76	      case "source":
77	        requireInteger(place.island, `${rubbing.id} island`);
78	        if (place.island < 0 || place.island >= config.islandNames.length) throw new RangeError(`rubbing ${rubbing.id} names an unknown island ${place.island}`);
79	        requireInteger(place.x, `${rubbing.id}.x`);
80	        requireInteger(place.y, `${rubbing.id}.y`);
81	        sources.push({ type: rubbing.type, island: place.island, sector: sectorOf(config, place) });
82	        break;
83	      case "cache":
84	        requireInteger(place.x, `${rubbing.id}.x`);
85	        requireInteger(place.y, `${rubbing.id}.y`);
86	        caches.push({ type: rubbing.type, sector: sectorOf(config, place) });
87	        break;
88	      case "carried":
89	      case "duel": {
90	        const holder = players.get(place.playerId);
91	        if (holder === undefined) throw new RangeError(`rubbing ${rubbing.id} is with ${String(place.playerId)}, who is not in the view`);
92	        const types = held.get(holder.id)!;
93	        if (types.includes(rubbing.type)) throw new RangeError(`player ${holder.id} holds two ${rubbing.type} rubbings`);
94	        types.push(rubbing.type);
95	        carriers.push({ sector: sectorOf(config, holder), type: rubbing.type, holder: holder.id });
96	        break;
97	      }
98	      default:
99	        throw new RangeError(`rubbing ${rubbing.id} has an unknown place`);
100	    }
101	  }
102	  for (const types of held.values()) types.sort(byTypeOrder);
103	  carriers.sort((a, b) => a.sector - b.sector || byTypeOrder(a.type, b.type) || compareIds(a.holder, b.holder));
104	  return { tick: view.tick, players, held, sources, caches, carriers };
105	}
106	
107	// ---------------------------------------------------------------------------------------------------------------------
108	// Planning a lead: sealed sources first, then caches, then a carrier sighting when every other copy is carried.
109	
110	type LeadPlan =
111	  | { readonly kind: "journal"; readonly options: readonly { readonly type: RubbingType; readonly target: IntelLeadTarget }[] }
112	  | {
113	      readonly kind: "carrier";
114	      /** The wanted types whose every copy is carried by someone else. */
115	      readonly types: readonly RubbingType[];
116	      /** Before the carrier reveal, one sighting per player per snapshot. */
117	      readonly capped: boolean;
118	      /** Distinct (type, sector) pairs from the previous snapshot, the player's own entries left out. */
119	      readonly options: readonly { readonly type: RubbingType; readonly sector: number }[];
120	      readonly seenTick: number;
121	    }
122	  | { readonly kind: "none" };
123	
124	interface LeadHolder {
125	  readonly id: string;
126	  readonly journal: readonly JournalRumor[];
127	  readonly lastSightingBoundary: number;
128	}
129	
130	function sameTarget(a: IntelLeadTarget, b: IntelLeadTarget): boolean {
131	  return a.kind === "island" ? b.kind === "island" && a.island === b.island : b.kind === "sector" && a.sector === b.sector;
132	}
133	
134	function uniqueSorted(values: readonly number[]): number[] {
135	  return [...new Set(values)].sort((a, b) => a - b);
136	}
137	
138	function planLead(
139	  config: IntelConfig,
140	  world: WorldIndex,
141	  snapshots: readonly CarrierSnapshot[],
142	  player: LeadHolder,
143	  types: readonly RubbingType[],
144	): LeadPlan {
145	  const held = world.held.get(player.id) ?? [];
146	  const wanted = config.types.filter((type) => types.includes(type) && !held.includes(type));
147	  const active = player.journal.filter((rumor) => rumor.status === "active");
148	  const fresh = (type: RubbingType, target: IntelLeadTarget) => !active.some((rumor) => rumor.type === type && sameTarget(rumor.target, target));
149	
150	  const islands = wanted.flatMap((type) =>
151	    uniqueSorted(world.sources.filter((source) => source.type === type).map((source) => source.island))
152	      .map((island) => ({ type, target: { kind: "island", island } as const }))
153	      .filter((option) => fresh(option.type, option.target)),
154	  );
155	  if (islands.length > 0) return { kind: "journal", options: islands };
156	  const sectors = wanted.flatMap((type) =>
157	    uniqueSorted(world.caches.filter((cache) => cache.type === type).map((cache) => cache.sector))
158	      .map((sector) => ({ type, target: { kind: "sector", sector } as const }))
159	      .filter((option) => fresh(option.type, option.target)),
160	  );
161	  if (sectors.length > 0) return { kind: "journal", options: sectors };
162	
163	  const carried = wanted.filter(
164	    (type) =>
165	      !world.sources.some((source) => source.type === type) &&
166	      !world.caches.some((cache) => cache.type === type) &&
167	      world.carriers.some((carrier) => carrier.type === type && carrier.holder !== player.id),
168	  );
169	  if (carried.length === 0) return { kind: "none" };
170	  const newest = snapshots.at(-1);
171	  const older = snapshots.length === 2 ? snapshots[0]! : undefined;
172	  const capped = world.tick < config.carrierRevealTick && newest !== undefined && player.lastSightingBoundary === newest.boundary;
173	  const options: { type: RubbingType; sector: number }[] = [];
174	  for (const entry of older?.entries ?? []) {
175	    if (entry.holder === player.id || !carried.includes(entry.type)) continue;
176	    if (!options.some((option) => option.type === entry.type && option.sector === entry.sector)) options.push({ type: entry.type, sector: entry.sector });
177	  }
178	  options.sort((a, b) => byTypeOrder(a.type, b.type) || a.sector - b.sector);
179	  return { kind: "carrier", types: carried, capped, options, seenTick: older?.tick ?? -1 };
180	}
181	
182	/**
183	 * What buying a targeted rumor for `type` would yield for `playerId` now, from the state after its last step and the
184	 * world view of that tick or a later one, without drawing from the generator. A step on a later tick can differ only
185	 * if it first crosses a snapshot boundary or spends the player's sighting on a free trigger.
186	 */
187	export function targetedRumorAvailability(
188	  config: IntelConfig,
189	  state: IntelState,
190	  view: IntelWorldView,
191	  playerId: string,
192	  type: RubbingType,
193	): Exclude<TargetedRumorResult, "duplicate"> {
194	  const world = readView(config, view, state.tick - 1);
195	  if (!state.started || !world.players.has(playerId) || !config.types.includes(type)) return "none";
196	  const player = state.players.find((candidate) => candidate.id === playerId) ?? { id: playerId, journal: [], lastSightingBoundary: -1 };
197	  return targetedResult(planLead(config, world, state.snapshots, player, [type]));
198	}
199	
200	function targetedResult(plan: LeadPlan): Exclude<TargetedRumorResult, "duplicate"> {
201	  if (plan.kind === "journal") return "rumor";
202	  if (plan.kind === "none") return "none";
203	  if (plan.capped) return "capped";
204	  return plan.options.length > 0 ? "sighting" : "none";
205	}
206	
207	// ---------------------------------------------------------------------------------------------------------------------
208	// The step.
209	
210	interface WorkingPlayer {
211	  id: string;
212	  held: readonly RubbingType[];
213	  journal: JournalRumor[];
214	  routeActive: boolean;
215	  routeEver: boolean;
216	  lastSightingBoundary: number;
217	  pending: PendingSighting | null;
218	}
219	
220	function working(player: IntelPlayerState): WorkingPlayer {
221	  return { ...player, journal: [...player.journal] };
222	}
223	
224	function frozen(player: WorkingPlayer): IntelPlayerState {
225	  return {
226	    id: player.id,
227	    held: [...player.held],
228	    journal: player.journal,
229	    routeActive: player.routeActive,
230	    routeEver: player.routeEver,
231	    lastSightingBoundary: player.lastSightingBoundary,
232	    pending: player.pending,
233	  };
234	}
235	
236	function sectorRef(config: IntelConfig, sector: number): SectorRef {
237	  return { sector, name: sectorName(config, sector) };
238	}
239	
240	/** The latest boundary `origin + k × interval` at or before `tick`, or -1 before `origin`. */
241	function boundaryIndex(tick: number, origin: number, interval: number): number {
242	  return tick < origin ? -1 : Math.floor((tick - origin) / interval);
243	}
244	
245	/**
246	 * One world tick of the information rules, in a fixed order:
247	 *
248	 * 1. Crossing a carrier boundary (every interval from control start) takes a snapshot of the carried copies; the
249	 *    latest two are kept.
250	 * 2. Per player, by id: a starting rumor (at control start, or on first appearance after it); otherwise the diff of
251	 *    held types resolves rumors for types gained, delivers the deferred sighting message at a boundary, and gives a
252	 *    free fresh rumor per type lost; then rumors whose target was emptied go stale and get a replacement; last, a completed or
253	 *    broken full set announces the final sector and sends or suspends the route.
254	 * 3. Targeted requests, by request id: each gets one outcome; a repeated id gets `duplicate` and changes nothing.
255	 * 4. The minute-20 sector reveal and the minute-28 carrier broadcasts, when their boundary was crossed.
256	 *
257	 * Boundaries fire when crossed since the last processed tick, so a skipped tick never loses one. Before control start
258	 * only the held types are tracked, and no message is sent. The input state is never mutated.
259	 */
260	export function stepIntel(
261	  config: IntelConfig,
262	  state: IntelState,
263	  view: IntelWorldView,
264	  requests: readonly TargetedRumorRequest[] = [],
265	): IntelStepResult {
266	  const world = readView(config, view, state.tick);
267	  for (const request of requests) {
268	    requireId(request.requestId, "request id");
269	    requireId(request.playerId, "request player id");
270	    if (typeof request.type !== "string") throw new RangeError(`request ${request.requestId} has no type`);
271	  }
272	  const tick = world.tick;
273	  let rng = state.rng;
274	  const draw = (bound: number): number => {
275	    const drawn = nextInt(rng, bound);
276	    rng = drawn.state;
277	    return drawn.value;
278	  };
279	  const messages: IntelMessage[] = [];
280	  const toPlayer = (playerId: string, body: IntelMessageBody) => messages.push({ to: { kind: "player", playerId }, body });
281	  const toEveryone = (body: IntelMessageBody) => messages.push({ to: { kind: "everyone" }, body });
282	
283	  const previous = new Map(state.players.map((player) => [player.id, player]));
284	  const players: WorkingPlayer[] = [...world.players.keys()].sort(compareIds).map((id) => {
285	    const known = previous.get(id);
286	    return known
287	      ? working(known)
288	      : { id, held: [], journal: [], routeActive: false, routeEver: false, lastSightingBoundary: -1, pending: null };
289	  });
290	
291	  // Requests: duplicates are answered without touching anything; the rest are recorded once.
292	  const seen = new Set(state.requestIds);
293	  const outcomes = new Map<number, TargetedRumorResult>();
294	  const accepted: { index: number; request: TargetedRumorRequest }[] = [];
295	  requests.forEach((request, index) => {
296	    if (seen.has(request.requestId)) {
297	      outcomes.set(index, "duplicate");
298	      return;
299	    }
300	    seen.add(request.requestId);
301	    accepted.push({ index, request });
302	  });
303	  const requestIds = seen.size === state.requestIds.length ? state.requestIds : [...seen].sort(compareIds);
304	  const answer = (): TargetedRumorOutcome[] => requests.map((request, index) => ({ requestId: request.requestId, result: outcomes.get(index)! }));
305	
306	  if (tick < config.controlStartTick) {
307	    for (const { index } of accepted) outcomes.set(index, "none");
308	    for (const player of players) player.held = world.held.get(player.id)!;
309	    return { state: { ...state, tick, players: players.map(frozen), requestIds }, messages, outcomes: answer() };
310	  }
311	
312	  // 1. Carrier snapshots.
313	  let snapshots = state.snapshots;
314	  const boundary = boundaryIndex(tick, config.controlStartTick, config.carrierIntervalTicks);
315	  const crossedBoundary = boundary > (snapshots.at(-1)?.boundary ?? -1);
316	  if (crossedBoundary) snapshots = [...snapshots, { boundary, tick, entries: world.carriers }].slice(-2);
317	
318	  const deliverRumor = (player: WorkingPlayer, plan: Extract<LeadPlan, { kind: "journal" }>, reason: IntelLeadReason): void => {
319	    const { type, target } = plan.options[draw(plan.options.length)]!;
320	    const entry = player.journal.length + 1;
321	    player.journal.push({ entry, type, target, reason, tick, status: "active", closedTick: null });
322	    toPlayer(player.id, {
323	      kind: "rumor",
324	      tick,
325	      entry,
326	      type,
327	      reason,
328	      target:
329	        target.kind === "island"
330	          ? { kind: "island", island: target.island, name: config.islandNames[target.island]! }
331	          : { kind: "sector", sector: target.sector, name: sectorName(config, target.sector) },
332	    });
333	  };
334	  /** One sighting message, which spends the player's sighting for this snapshot: per asked type, one of its sectors. */
335	  const deliverSighting = (
336	    player: WorkingPlayer,
337	    plan: Extract<LeadPlan, { kind: "carrier" }>,
338	    asked: readonly { readonly type: RubbingType; readonly reason: IntelLeadReason }[],
339	  ): void => {
340	    const sightings = asked.map(({ type, reason }) => {
341	      const sectors = plan.options.filter((option) => option.type === type);
342	      const { sector } = sectors[draw(sectors.length)]!;
343	      return { type, reason, sector, name: sectorName(config, sector) };
344	    });
345	    player.lastSightingBoundary = snapshots.at(-1)!.boundary;
346	    toPlayer(player.id, { kind: "carrier-sighting", tick, seenTick: plan.seenTick, sightings });
347	  };
348	  /** Adds types to the player's one pending sighting message, each type once, in type order. */
349	  const defer = (player: WorkingPlayer, types: readonly RubbingType[], reason: PendingSightingType["reason"]): void => {
350	    const pending = [...(player.pending?.types ?? [])];
351	    for (const type of types) if (!pending.some((entry) => entry.type === type)) pending.push({ type, reason, tick });
352	    pending.sort((a, b) => byTypeOrder(a.type, b.type));
353	    player.pending = pending.length > 0 ? { types: pending } : null;
354	  };
355	  /**
356	   * Replans every pending type: a type that now has a journal target gets a rumor, one with nothing left a no-lead,
357	   * and every type with an entry in the previous snapshot goes out together in one sighting message unless capped. The
358	   * rest keep waiting.
359	   */
360	  const flushPending = (player: WorkingPlayer): void => {
361	    const waiting = player.pending?.types ?? [];
362	    player.pending = null;
363	    const asked: PendingSightingType[] = [];
364	    const kept: PendingSightingType[] = [];
365	    let carrierPlan: Extract<LeadPlan, { kind: "carrier" }> | undefined;
366	    for (const pending of waiting) {
367	      const plan = planLead(config, world, snapshots, player, [pending.type]);
368	      if (plan.kind === "journal") deliverRumor(player, plan, pending.reason);
369	      else if (plan.kind === "none") toPlayer(player.id, { kind: "no-lead", tick, type: pending.type, reason: pending.reason });
370	      else if (!plan.capped && plan.options.length > 0) {
371	        asked.push(pending);
372	        carrierPlan = carrierPlan === undefined ? plan : { ...carrierPlan, options: [...carrierPlan.options, ...plan.options] };
373	      } else kept.push(pending);
374	    }
375	    if (carrierPlan !== undefined) deliverSighting(player, carrierPlan, asked);
376	    player.pending = kept.length > 0 ? { types: kept } : null;
377	  };
378	  /**
379	   * A free lead (start, loss or journal replacement). A sighting joins the player's pending message, which goes out now
380	   * unless capped or data-less; otherwise it waits for the next boundary.
381	   */
382	  const freeLead = (player: WorkingPlayer, types: readonly RubbingType[], reason: PendingSightingType["reason"]): void => {
383	    const plan = planLead(config, world, snapshots, player, types);
384	    if (plan.kind === "journal") return deliverRumor(player, plan, reason);
385	    if (plan.kind === "carrier") {
386	      defer(player, plan.types, reason);
387	      if (!plan.capped) flushPending(player);
388	      return;
389	    }
390	    const lacking = config.types.filter((type) => types.includes(type) && !(world.held.get(player.id) ?? []).includes(type));
391	    if (lacking.length > 0) toPlayer(player.id, { kind: "no-lead", tick, type: lacking[0]!, reason });
392	  };
393	
394	  // 2. Players.
395	  const startCrossed = !state.started;
396	  let finalAnnounced = state.finalSectorAnnounced;
397	  for (const player of players) {
398	    const held = world.held.get(player.id)!;
399	    if (startCrossed || !previous.has(player.id)) {
400	      player.held = held;
401	      freeLead(player, config.types, "start");
402	    } else {
403	      const gained = held.filter((type) => !player.held.includes(type));
404	      const lost = player.held.filter((type) => !held.includes(type));
405	      player.held = held;
406	      // Types obtained retire their rumors quietly and cancel their deferred sightings.
407	      player.journal = player.journal.map((rumor) => {
408	        if (rumor.status !== "active" || !gained.includes(rumor.type)) return rumor;
409	        toPlayer(player.id, { kind: "rumor-resolved", tick, entry: rumor.entry, type: rumor.type });
410	        return { ...rumor, status: "resolved", closedTick: tick };
411	      });
412	      const stillWanted = player.pending?.types.filter((pending) => !held.includes(pending.type)) ?? [];
413	      player.pending = stillWanted.length > 0 ? { types: stillWanted } : null;
414	      // At a boundary the pending message goes out with every pending type that is still eligible.
415	      if (crossedBoundary) flushPending(player);
416	      // §11: a free fresh rumor for each type lost. Entering a duel is no loss: reserved copies still count as held.
417	      for (const type of lost) freeLead(player, [type], "fresh");
418	    }
419	
420	    // Journal rumors whose island or cache sector no longer holds the type go stale, then get a replacement.
421	    const emptied: RubbingType[] = [];
422	    player.journal = player.journal.map((rumor) => {
423	      if (rumor.status !== "active") return rumor;
424	      const { target } = rumor;
425	      const holds =
426	        target.kind === "island"
427	          ? world.sources.some((source) => source.type === rumor.type && source.island === target.island)
428	          : world.caches.some((cache) => cache.type === rumor.type && cache.sector === target.sector);
429	      if (holds) return rumor;
430	      toPlayer(player.id, { kind: "rumor-stale", tick, entry: rumor.entry, type: rumor.type });
431	      emptied.push(rumor.type);
432	      return { ...rumor, status: "stale", closedTick: tick };
433	    });
434	    for (const type of emptied) freeLead(player, [type], "replacement");
435	
436	    // §5: the first full set announces the final sector to everyone; each holder gets the route while the set is whole.
437	    const complete = config.types.every((type) => held.includes(type));
438	    if (complete && !player.routeActive) {
439	      if (!finalAnnounced) {
440	        finalAnnounced = true;
441	        const sector = sectorOf(config, config.finalIsland);
442	        toEveryone({ kind: "final-sector", tick, sector, name: sectorName(config, sector) });
443	      }
444	      toPlayer(player.id, { kind: "final-route", tick, x: config.finalIsland.x, y: config.finalIsland.y, restored: player.routeEver });
445	      player.routeActive = true;
446	      player.routeEver = true;
447	    } else if (!complete && player.routeActive) {
448	      toPlayer(player.id, { kind: "final-route-inactive", tick });
449	      player.routeActive = false;
450	    }
451	  }
452	
453	  // 3. Targeted rumors (§11), by request id so the order they were listed in never matters.
454	  const byId = new Map(players.map((player) => [player.id, player]));
455	  for (const { index, request } of [...accepted].sort((a, b) => compareIds(a.request.requestId, b.request.requestId) || a.index - b.index)) {
456	    const player = byId.get(request.playerId);
457	    if (player === undefined || !config.types.includes(request.type)) {
458	      outcomes.set(index, "none");
459	      continue;
460	    }
461	    const plan = planLead(config, world, snapshots, player, [request.type]);
462	    const result = targetedResult(plan);
463	    if (result === "rumor") deliverRumor(player, plan as Extract<LeadPlan, { kind: "journal" }>, "targeted");
464	    if (result === "sighting") deliverSighting(player, plan as Extract<LeadPlan, { kind: "carrier" }>, [{ type: request.type, reason: "targeted" }]);
465	    outcomes.set(index, result);
466	  }
467	
468	  // 4. Timed reveals (§2).
469	  let sectorRevealed = state.sectorRevealed;
470	  if (!sectorRevealed && tick >= config.sectorRevealTick) {
471	    sectorRevealed = true;
472	    toEveryone({
473	      kind: "sector-reveal",
474	      tick,
475	      sources: uniqueSorted(world.sources.map((source) => source.sector)).map((sector) => sectorRef(config, sector)),
476	      caches: uniqueSorted(world.caches.map((cache) => cache.sector)).map((sector) => sectorRef(config, sector)),
477	    });
478	  }
479	  let lastCarrierBroadcast = state.lastCarrierBroadcast;
480	  const broadcast = boundaryIndex(tick, config.carrierRevealTick, config.carrierIntervalTicks);
481	  if (broadcast > lastCarrierBroadcast) {
482	    lastCarrierBroadcast = broadcast;
483	    const newest = snapshots.at(-1)!;
484	    const carriers: (SectorRef & { type: RubbingType })[] = [];
485	    for (const entry of newest.entries) {
486	      if (!carriers.some((carrier) => carrier.sector === entry.sector && carrier.type === entry.type)) {
487	        carriers.push({ ...sectorRef(config, entry.sector), type: entry.type });
488	      }
489	    }
490	    toEveryone({ kind: "carrier-report", tick, seenTick: newest.tick, carriers });
491	  }
492	
493	  return {
494	    state: {
495	      tick,
496	      rng,
497	      started: true,
498	      players: players.map(frozen),
499	      snapshots,
500	      finalSectorAnnounced: finalAnnounced,
501	      sectorRevealed,
502	      lastCarrierBroadcast,
503	      requestIds,
504	    },
505	    messages,
506	    outcomes: answer(),
507	  };
508	}
509	
510	export interface IntelReplayTick {
511	  readonly view: IntelWorldView;
512	  readonly requests?: readonly TargetedRumorRequest[];
513	}
514	
515	export interface IntelReplay {
516	  readonly state: IntelState;
517	  readonly messages: readonly IntelMessage[];
518	  readonly outcomes: readonly TargetedRumorOutcome[];
519	  readonly hash: string;
520	}
521	
522	/** Steps a sequence of views from a state, collecting every message and outcome; `hash` is the final `hashState`. */
523	export function replayIntel(config: IntelConfig, state: IntelState, ticks: readonly IntelReplayTick[]): IntelReplay {
524	  let current = state;
525	  const messages: IntelMessage[] = [];
526	  const outcomes: TargetedRumorOutcome[] = [];
527	  for (const { view, requests } of ticks) {
528	    const stepped = stepIntel(config, current, view, requests ?? []);
529	    current = stepped.state;
530	    messages.push(...stepped.messages);
531	    outcomes.push(...stepped.outcomes);
532	  }
533	  return { state: current, messages, outcomes, hash: hashState(current) };
534	}
